// План specs/mobile-nav.md 3.1–3.8 (#0e73d5, связан MN-02 / #c264a7). PROD, admin, компания «test». Только просмотр (@prod-safe):
// меню открывается и замеряется, пункты не нажимаются (GPS Workflow при первом открытии покупает номер Twilio).
// Источник: «מה רצוי» — все пункты меню видны без прокрутки и на 375×812 (пример — меньший интервал между пунктами). Комментарий программиста (15a34ac):
// высота пункта 44 px при наличии места, на низком экране пункты сжимаются до 36 px — все пункты без прокрутки.
// Факты 17.11 (эмуляция): все пункты без прокрутки на 375×629 / 667 / 812 и 360×640, EN и HE. Реальный Safari не проверен — 375×… идёт в iPhone-прогоне (WebKit),
// 360×640 — в Android-прогоне. Пункты берутся из mobile-nav-helpers (16 пунктов admin; если появится 17-й — обновить ITEMS).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, ITEMS, Lang, openMoreMenu, restoreCompany, scrollOverflows } from './mobile-nav-helpers';

test.use({ storageState: ADMIN_STATE });

const SCREENS = [
  { label: '375x812', viewport: { width: 375, height: 812 }, tag: '@iphone' },
  { label: '375x667', viewport: { width: 375, height: 667 }, tag: '@iphone' },
  { label: '375x629', viewport: { width: 375, height: 629 }, tag: '@iphone' },
  { label: '360x640', viewport: { width: 360, height: 640 }, tag: '@android' },
] as const;

for (const screen of SCREENS) {
  test.describe(`Phone ${screen.label}: side menu fits without scrolling (#0e73d5)`, () => {
    test.use({ viewport: screen.viewport });

    for (const lang of ['en', 'he'] as Lang[]) {
      test(`Side menu ${screen.label} ${lang.toUpperCase()}: last item "${ITEMS[lang][ITEMS[lang].length - 1]}" fully visible, no vertical scroll #0e73d5 ${screen.tag} @prod-safe`, async ({ page }) => {
        try {
          const { panel, items } = await openMoreMenu(page, lang);
          expect(await scrollOverflows(panel, items[0]), 'контейнер меню без вертикальной прокрутки').toEqual([]);

          const last = (await items[items.length - 1].boundingBox())!;
          const vh = screen.viewport.height;
          expect(last.y, 'последний пункт: верх на экране').toBeGreaterThanOrEqual(0);
          expect(last.y + last.height, `последний пункт не обрезан: низ ≤ высоты экрана ${vh}`).toBeLessThanOrEqual(vh + 0.5);
          await expect(items[items.length - 1]).toBeInViewport({ ratio: 1 });
        } finally {
          await restoreCompany(page);
        }
      });
    }
  });
}
